int tipc_dump(struct sk_buff *skb, struct netlink_callback *cb)
{
    int ret = 0;
    int port_id;
    struct tipc_sock *tsk;

    if (cb->args[0]) {
        port_id = cb->args[1];
    } else {
        port_id = nla_get_u32(skb);
        if (!port_id)
            return -EINVAL;
    }

    if (cb->args[2]) {
        return skb->len;
    }

    tsk = tipc_sk_lookup(port_id);
    if (!tsk)
        return -ENOENT;

    lock_sock(tsk);

    ret = tipc_sk_publish_info(skb, cb->args[0], cb->args[2]);
    if (ret < 0)
        goto out;

    cb->args[0] = port_id;
    cb->args[2] = 1;

    skb->len = ret;

out:
    release_sock(tsk);
    sock_put(&tsk->sk);
    return ret;
}

int tipc_dump(struct sk_buff *skb, struct netlink_callback *cb)
{
    int port_id;
    struct tipc_socket *sock;
    int ret = 0;

    if (!cb->args[0]) {
        port_id = nla_get_u32(cb->nlh->nlmsg_data);
    } else {
        port_id = cb->args[1];
    }

    if (cb->args[2])
        return skb->len;

    sock = tipc_sk_lookup_portid(port_id);
    if (!sock)
        return -ENOENT;

    mutex_lock(&sock->lock);

    if (sock->last_publ) {
        tipc_dump_list(skb, sock, cb);
        cb->args[2] = 1;
    }

    cb->args[0] = port_id;
    cb->args[1] = sock->last_publ;
    mutex_unlock(&sock->lock);

    return skb->len;
}

int tipc_dump_sk(struct sk_buff *skb, struct netlink_callback *cb)
{
    int pid = NETLINK_CB(skb).portid;
    int family = 0;
    int done = 0;
    int last_publ = 0;
    struct tipc_sock *tsk;

    if (!pid)
        return -EINVAL;

    if (done)
        return skb->len;

    tsk = tipc_sk_lookup(pid);
    if (!tsk)
        return -ENOENT;

    tipc_sk_lock(tsk);

    if (!last_publ)
        tipc_sk_publish(tsk, family, skb, cb);

    tipc_sk_unlock(tsk);
    done = 1;
    cb->args[0] = family;
    cb->args[1] = last_publ;
    cb->args[2] = done;

    return skb->len;
}

int tipc_sk_dump(struct sk_buff *skb, struct netlink_callback *cb)
{
    int portid = 0;

    if (!cb->args[0])
        portid = nlmsg_parse(skb, cb->nlh, NULL, 0, NULL);

    if (cb->args[1])
        return skb->len;

    if (!portid)
        return -EINVAL;

    struct tipc_port *port = tipc_port_get(portid);
    if (!port)
        return -ENOENT;

    spin_lock_bh(&port->lock);
    if (!port->published)
        goto out;

    if (!cb->args[0]) {
        cb->args[0] = portid;
        cb->args[1] = 1;
    }

    if (port->published > cb->args[2]) {
        cb->args[2]++;
        skb->data_len += port->published_len;
    } else {
        cb->done = 1;
    }

    spin_unlock_bh(&port->lock);
    return skb->len;

out:
    spin_unlock_bh(&port->lock);
    return -EIO;
}

int tipc_sk_dump(struct sk_buff *skb, struct netlink_callback *cb)
{
    int port_id;

    if (!cb->args[0])
        port_id = nlmsg_parse(skb, 0, &cb->msg, 0, NULL);

    if (cb->args[1])
        return skb->len;

    port_id = (int)cb->args[0];
    if (port_id <= 0)
        return -EINVAL;

    struct tipc_port *port = tipc_port_find(port_id);
    if (!port)
        return -ENOENT;

    spin_lock_bh(&port->lock);
    if (!port->publ_list)
        goto skip_publish;

    struct tipc_publish *publ = port->last_publ;
    if (!publ) {
        publ = list_first_entry(&port->publ_list, struct tipc_publish, list);
    } else {
        publ = list_next_entry(publ, list);
        if (&publ->list == &port->publ_list)
            cb->args[1] = 1;
    }

    if (!cb->args[1]) {
        port->last_publ = publ;
        cb->args[0] = publ;
    }

skip_publish:
    spin_unlock_bh(&port->lock);

    cb->args[0] = port_id;
    cb->args[1] = cb->args[1] ? 1 : 0;

    return skb->len;
}
